4	import java.util.UUID;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * The single definition of what makes owners share a household: the same last name (compared
11	 * case-insensitively after collapsing runs of whitespace) and the same address in its normalized
12	 * form (see {@link AddressNormalizer}). Shared by {@link AssignHousehold} (which links a
13	 * {@code sharesHousehold} owner to the existing members and assigns the shared {@code householdId})
14	 * and {@link RequireUniqueIdentity} (which derives the candidate's household id for its identity key),
15	 * so both apply the same rule and cannot drift apart.
16	 *
17	 * <p>Also owns the deterministic {@code householdId} derived from that key: joining the same household
18	 * always yields the same value and it never changes over time.
19	 *
20	 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
21	 * expose exactly one public method.
22	 */
23	final class HouseholdKey {
24	
25	    private final String lastName;
26	
27	    private final String address;
28	
29	    private HouseholdKey(String lastName, String address) {
30	        this.lastName = lastName;
31	        this.address = address;
32	    }
33	
34	    /** The household key for the given last name and address. */
35	    static HouseholdKey of(String lastName, String address) {
36	        return new HouseholdKey(normalize(lastName), AddressNormalizer.normalize(address));
37	    }
38	
39	    /**
40	     * The effective {@code householdId} a create request would carry: the deterministic
41	     * {@link #householdId()} when the request opts into {@code sharesHousehold}, otherwise
42	     * {@code null} (the owner joins no household). The single home of the share-or-not gate, so
43	     * {@link RequireUniqueIdentity} (which folds it into the identity key) and {@link AssignHousehold}
44	     * (which assigns it) cannot drift apart.
45	     */
46	    static String candidateHouseholdId(OwnerFieldsDto request) {
47	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
48	            return null;
49	        }
50	        return of(request.getLastName(), request.getAddress()).householdId();
51	    }
52	
53	    /** True when the existing owner belongs to this household. */
54	    boolean matches(Owner owner) {
55	        return this.lastName.equals(normalize(owner.getLastName()))
56	                && this.address.equals(AddressNormalizer.normalize(owner.getAddress()));
57	    }
58	
59	    /** A stable, shared identifier derived from the normalized last name and address. */
60	    String householdId() {
61	        String key = this.lastName + "\u0000" + this.address;
62	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
63	    }
64	
65	    /** Lower-cases and collapses runs of whitespace to a single space for case- and
66	     *  whitespace-insensitive comparison. */
67	    private static String normalize(String value) {
68	        if (value == null) {
69	            return "";
70	        }
71	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
72	    }
73	}
